// Restore character goals from the private notes generated by v8.
export function migrateAspirations(p, notes) {
  p.aspirations ??= { ambition: '', desire: '' };
  if (
    p.aspiration_migration_v9 &&
    !(p.goals || []).length &&
    !notes.some((n) => n.id?.startsWith(`legacy-${p.id}-goals-`) && n.character_id === p.id)
  )
    return;
  const rows = (p.goals || []).map((row, i) => ({ ...row, kind: i === 0 ? 'ambition' : 'desire' }));
  for (const note of notes.filter(
    (n) => n.id?.startsWith(`legacy-${p.id}-goals-`) && n.character_id === p.id
  )) {
    const kind = /^desejo(?:\s|$)/i.test(note.title)
      ? 'desire'
      : /^ambi[çc][ãa]o(?:\s|$)/i.test(note.title)
        ? 'ambition'
        : rows.length
          ? 'desire'
          : 'ambition';
    rows.push({ ...note, kind, description: note.content });
  }
  for (const row of rows) {
    const value = String(row.description || row.content || '').trim();
    if (!value) continue;
    if (!p.aspirations[row.kind]) p.aspirations[row.kind] = value;
    else if (p.aspirations[row.kind] !== value) {
      p.history ??= [];
      p.history.push({
        id: `aspiration-import-${p.id}-${row.id}`,
        at: row.created_at || p.updated_at || new Date().toISOString(),
        actor: 'Migração do portal',
        action: 'Objetivo anterior preservado',
        details: `${row.kind === 'ambition' ? 'Ambição' : 'Desejo'}: ${value}`
      });
    }
  }
  p.goals = [];
  p.aspiration_migration_v9 = true;
}
